// A glob's text, normalized as globToRegExp reads it, matches its own pattern, so the gate's rule reads it as a path.
const toCreate = scopeIn.filter(
  (glob, index) =>
    !matched.has(index) &&
    scopedPaths([glob.trim().replace(/^\.\//, '')], [glob], task.scopeOut).length > 0,
);
